insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8ae8c1d6-4a69-4a78-8255-8f7a954e4608', 'de', 'Café. Du sagst etwas zur langen Schlange. Sie lächelt, antwortet mit einem Witz und dreht sich zu dir.', '["Sie ist höflich, weil du zuerst etwas gesagt hast", "Sie ist offen und bereit, weiterzureden", "Sie vertreibt sich nur die Wartezeit"]'::jsonb, 'Humor und Zuwendung zeigen Interesse. Sie macht mit, statt nur zu antworten.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8ce90839-46ac-4c09-88d3-7e5231bbade8', 'de', 'Du siehst ein cooles Tattoo an ihrem Arm. Welcher Opener zeigt Neugier?', '["„Was ist die Geschichte hinter dem Tattoo? Sieht echt cool aus.“", "„Das Tattoo sieht an dir heiß aus.“", "„Du hast coolen Stil.“", "„Hast du noch mehr Tattoos?“"]'::jsonb, 'Neugier auf ihre Erlebnisse lädt zu einer echten Verbindung ein, ohne Hintergedanken.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('90a2ae5f-3f19-4289-983b-90a3660b1de9', 'de', 'Was passiert, wenn jemand höfliche oder kühle Signale ignoriert?', '["Die Anziehung wächst langsam", "Das Wohlgefühl sinkt", "Das Gespräch wird tiefer", "Das Interesse wird klarer"]'::jsonb, 'Wer Signale ignoriert, sorgt für Anspannung und Unbehagen. Geh, sobald du solche Signale bemerkst.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('92fc8147-e976-4d33-824a-5ea94444d15c', 'de', 'Warum funktionieren falsche Vermutungen oft trotzdem?', '["Auch eine Korrektur bezieht sie ein und bringt Schwung", "Danebenliegen senkt den Druck", "Frauen korrigieren Männer gern"]'::jsonb, 'Ob du richtigliegst oder nicht: Um zu antworten, muss sie sich einbringen. Genau darum geht es.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('94a93921-8975-4a5a-ac8a-918d2cfeb071', 'de', 'Warum solltest du mit Neugier ansprechen?', '["Sie verbirgt die Anziehung", "Sie verhindert Abfuhren", "Sie funktioniert wie ein psychologischer Trick", "Sie senkt den Druck und gibt ihr das Gefühl, interessant zu sein"]'::jsonb, 'Menschen öffnen sich, wenn sie sich gesehen fühlen, nicht bewertet oder gejagt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('95d93e33-2d1c-431f-a2f0-0ed76d7c559c', 'de', 'Fitnessstudio. Du sprichst sie an. Sie antwortet freundlich und steckt dann ihre Kopfhörer wieder rein.', '["Offen: Sie hat ausführlich geantwortet und zeigt Interesse", "Höflich: Sie hat aus Höflichkeit geantwortet, will aber nicht weiterreden", "Kühl: unhöfliches Verhalten, das dir sagt, du sollst sofort gehen"]'::jsonb, 'Sie hat dich wahrgenommen und dann eine Grenze gezogen. Zieh dich zurück, ohne es in die Länge zu ziehen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('96cd2c07-1109-4ded-b869-cec66cf863b9', 'de', 'Du sprichst sie in einer Bar direkt an. Ihre Freundin kommt dazu, und sie dreht sich leicht zu ihr.', '["Einfach weiterreden wie bisher", "Um Aufmerksamkeit konkurrieren", "Ansprechen, dass sie sich weggedreht hat", "Die Freundin begrüßen oder dich sauber verabschieden"]'::jsonb, 'Feingefühl heißt, dich anzupassen, wenn sich die Situation ändert.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('97f948e5-43c9-49fb-91ea-249d0532afa8', 'de', 'Auf einer Party steht sie bei den Getränken. Welcher direkte Opener passt am besten?', '["„Ich hab dich von drüben gesehen und musste dich einfach kennenlernen.“", "„Die Musik ist ganz schön laut, oder?“", "„Weißt du, wo das Bad ist?“", "„Bist du öfter hier?“"]'::jsonb, 'Klar gezeigtes Interesse passt ganz natürlich zu einer Party.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('99e493d5-07b4-4d19-ad59-483e3579a8d1', 'de', 'Was macht einen Opener, der nach ihrer Meinung fragt, wirksam?', '["Er erklärt, warum du gerade sie fragst und nicht irgendwen", "Er macht ihre Sicht wertvoll und wichtig", "Er schafft eine Diskussion, die Spannung und Anziehung aufbaut"]'::jsonb, 'Menschen blühen auf, wenn ihre Sicht zählt. Wertschätzung weckt Interesse.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9a58e14a-b997-4eae-a453-494d620dffc6', 'de', 'Bar. Du sagst: „Du bist eindeutig die Vernünftige, die am Ende alle nach Hause fährt.“ Was funktioniert hier?', '["Die konkrete Vermutung bringt sie dazu, sofort zu antworten und einzusteigen", "Sie ist neugierig, wie du darauf kommst", "Beides"]'::jsonb, 'Eine konkrete Vermutung verlangt nach einer Antwort und bezieht sie sofort ein.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9c7e0b10-8bac-4319-8672-b7ce62646374', 'de', 'Du stehst in einer vollen Bar neben ihr. Welche indirekten Opener gibt es?', '["Fragen, ob die Bar immer so voll ist", "Fragen, was sie bestellt", "Ihr sagen, dass sie attraktiv aussieht", "Nach ihrem Instagram fragen"]'::jsonb, 'Beobachtungen zur Umgebung wirken wie Mitmachen, nicht wie Stören.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9cf11184-5b92-4e5e-ac1b-12519aa0d194', 'de', 'Sie lächelt höflich, wendet sich aber nach einer kurzen Antwort wieder ihrem Handy zu. Was zeigt das?', '["Höfliche Duldung, kein echtes Interesse", "Starke Offenheit, schüchtern versteckt", "Eine kühle Abfuhr, bei der du dranbleiben musst", "Eine offene Einladung weiterzumachen"]'::jsonb, 'Ein höfliches Lächeln mit Rückzug zeigt Neutralität, kein Interesse.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9fb3d329-54bd-4b72-a37a-6435bb2ff6a4', 'de', 'Du sagst, wie lange es mit den Getränken dauert. Sie lächelt und stimmt begeistert zu.', '["Sie ist genervt und lässt Dampf ab, hat aber nicht unbedingt Interesse", "Sie testet, ob du ihren Beschwerden zustimmst", "Sie erwidert deine Energie und bleibt im Gespräch"]'::jsonb, 'Eine begeisterte Antwort und dass sie beim Thema bleibt, zeigen Interesse.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a02bd67f-f7f7-4331-a001-13bf4277f3f7', 'de', 'Warum funktioniert „Ich hab eine Frage“ als Einstieg besser, als die Frage gleich zu stellen?', '["Es zeigt Respekt, weil du um Erlaubnis fragst, bevor du ihre Zeit beanspruchst", "Es baut Vorfreude und Neugier auf, bevor die eigentliche Frage kommt", "Es gibt ihr Zeit, sich innerlich auf das Gespräch einzustellen"]'::jsonb, 'Wenn du die Frage ankündigst, baust du erst Neugier auf. Eine direkte Frage weckt keine Vorfreude.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a08ba78a-da12-481b-ae11-9fc1b34e1ee4', 'de', 'Was ist die wichtigste Erkenntnis darüber, wie Verbindungen entstehen?', '["Einer muss bereit sein, als Erster etwas zu sagen", "Sie entstehen wie von Zauberhand, ganz ohne Zutun", "Warten führt immer zu besseren Ergebnissen", "Schweigen führt zu tieferen Beziehungen"]'::jsonb, 'Jeder Freund, den du hast, ist dein Freund, weil einer von euch zuerst den Mund aufgemacht hat.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a0996b03-70aa-45f2-8b9b-1e136e46396e', 'de', 'Du steigst mit einer Bemerkung zur Situation ein. Sie lacht und ergänzt selbst etwas. Dein nächster Schritt?', '["Zu einem direkten Kompliment übergehen", "Beim Thema bleiben und etwas tiefer gehen", "Sofort nach ihrer Nummer fragen", "Sie verspielt aufziehen"]'::jsonb, 'Dass sie etwas beiträgt, zeigt Interesse. Wenn du vertiefst, bleibt der natürliche Schwung erhalten.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a2802fe7-bfee-46b8-9b7a-3b8797515730', 'de', 'Café. Sie geht auf dich ein. Der Barista ruft ihren Namen. Sie sagt: „Oh, das bin ich, sorry!“ Was ist das?', '["Offen, aber unterbrochen: Schnell vorschlagen, euch zusammenzusetzen", "Höflich: Sie nutzt das Abholen als bequemen Ausweg", "Störung von außen, kein Signal: Schau, ob sie nach dem Abholen zurückkommt"]'::jsonb, 'Vor der Unterbrechung war Interesse da. Schau, ob sie danach zurückkommt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a281e41d-8c59-42aa-8e23-5071d84c9c8c', 'de', 'Warum funktioniert „Mein Kumpel und ich diskutieren gerade …“ als Einstieg?', '["Es macht neugierig, worum es in der Diskussion geht", "Ihre Meinung entscheidet, und dadurch fühlt sie sich geschätzt", "Es zeigt sozialen Beweis, weil du Freunde hast"]'::jsonb, 'Eine kleine Streitfrage lädt sie ein, ihre Meinung zu sagen. So fühlt sie sich geschätzt und einbezogen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a445b565-f83a-4031-9b70-7201a9b11bc3', 'de', 'Was signalisierst du, wenn du die Richtung des Gesprächs vorgibst?', '["Selbstbewusstsein", "Führung", "Orientierung", "Alle oben genannten"]'::jsonb, 'Wenn du das Thema wählst, zeigst du Selbstbewusstsein und Führung. Gib die Richtung vor, statt zu warten.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a51060bf-7646-4967-a8bf-730e53f6714d', 'de', 'Warum weckt „Hi, ich hab eine Frage an dich“ so gut Neugier?', '["Es erzeugt Ungewissheit: Sie will wissen, was die Frage ist", "Es zeigt Selbstbewusstsein, weil du sie bei etwas unterbrichst", "Es zeigt, dass du etwas brauchst, und sie wird weniger vorsichtig"]'::jsonb, 'Wenn eine Information unvollständig ist, will das Gehirn sie ergänzen. Nutz das, um Aufmerksamkeit zu wecken.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a95654fc-2f4a-4b06-a6d7-ce66be1aaac1', 'de', 'Ihr stöbert beide in einem Buchladen. Welche indirekten Opener gibt es?', '["Fragen, ob sie dieses Buch kennt", "Ihr sagen, dass sie dir aufgefallen ist", "Nach ihrer Nummer fragen", "Etwas dazu sagen, wie gut der Autor ist"]'::jsonb, 'Opener, die eine Beobachtung aufgreifen, fügen sich in den Moment ein.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ab9eedd4-bf67-486a-8b3c-938ef10f4137', 'de', 'Warum ist es sinnvoll anzusprechen, statt stillzuhalten?', '["Nichtstun garantiert das Scheitern, Handeln schafft Möglichkeiten", "Ansprechen baut schneller Anziehung auf", "Handeln garantiert Selbstbewusstsein"]'::jsonb, 'Wenn du nichts tust, kann nichts passieren. Wenn du handelst, kann etwas passieren.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ad29d82a-7cad-4f44-8cd0-826bc8d6d751', 'de', 'Ein Typ bleibt auf einer Party still, während andere ins Gespräch kommen. Was fehlt ihm?', '["Besseres Timing", "Sozialer Status", "Freunde zum Reden", "Die Bereitschaft, auf andere zuzugehen"]'::jsonb, 'Ein Gespräch anzufangen ist der einfache Schritt, aus dem Verbindung entsteht.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ada0ea94-3879-4702-b335-f62a57dd6045', 'de', 'Warum werden höfliche Reaktionen so leicht als Interesse missverstanden?', '["Sie enthalten Blickkontakt und Freundlichkeit", "Frauen vermeiden schroffe Abfuhren", "Männer deuten ihr eigenes Verlangen in neutrale Signale hinein", "Alle oben genannten"]'::jsonb, 'Höfliche Signale sind bewusst sanft. Verlass dich lieber auf anhaltende Aufmerksamkeit und Gegenfragen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ae78311f-d702-432d-971c-a612871a0e09', 'de', 'Sie lächelt dich leicht an und dreht sich dann weg. Was rät die Drei-Sekunden-Regel?', '["Ihr Lächeln auf Interesse hin analysieren", "Auf ein deutlicheres Zeichen warten", "Sofort hingehen, bevor du ins Grübeln kommst", "Erst sorgfältig deine Worte planen"]'::jsonb, 'Schnelles Handeln kommt der wachsenden Liste an Gründen zuvor, die dein Kopf gegen das Hingehen sammelt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b147a697-dedb-4919-b533-e070ef0767f6', 'de', 'Wie vermeidest du, dass automatisch eine Bedrohungsreaktion ausgelöst wird?', '["Aus einem Winkel kommen, in dem sie dich sieht", "Ihr keine Wege oder Bewegungsmöglichkeiten versperren", "In respektvollem Abstand stehen bleiben", "Alle oben genannten"]'::jsonb, 'Wenn du ihren persönlichen Raum respektierst, wirkt das Gespräch ruhig und natürlich.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b22764cf-ce02-4bf8-8eb7-5fb7926333ed', 'de', 'Ihr Buch hat ein interessantes Cover. Womit könntest du einsteigen, um sie neugierig zu machen?', '["„Was ist das für ein Buch?“", "„Liest du viel?“", "„Das sieht interessant aus.“", "„Ich muss dich was zu dem Buch fragen, das du da hast.“"]'::jsonb, 'Die Ankündigung macht neugierig, bevor du die eigentliche Frage stellst.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b2eb7c50-c714-4003-a310-0084c29f7fcc', 'de', 'Warum nehmen indirekte Opener Druck raus?', '["Es sind eingeübte Sätze, die in vielen Situationen funktionieren", "Sie muss nicht sofort entscheiden, ob sie dich attraktiv findet", "Sie verstecken deine Absicht hinter einem lockeren, glaubwürdigen Gespräch"]'::jsonb, 'Indirekte Opener fühlen sich an wie eine Fortsetzung des Moments, in dem ihr beide schon seid.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b32bbd22-abe6-4fd4-9f13-deaaad94298d', 'de', 'Sie hat eine Handyhülle mit Pflanzenmotiv. Welcher Opener zeigt Neugier?', '["„Süße Hülle.“", "„Gärtnerst du?“", "„Dein Handy sieht schön aus.“", "„Stehst du auf Pflanzen? Da sind ein paar coole auf der Hülle.“"]'::jsonb, 'Neugier auf ihre Erlebnisse lädt zu einer echten Verbindung ein, ohne Hintergedanken.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b58b39df-93ba-4f7a-bed5-8eaaa5aa7a37', 'de', 'Sie tanzt mit Freundinnen. Ihr habt Blickkontakt, und sie lächelt. Was tust du?', '["Warten, bis sie eine Tanzpause macht", "In ihrer Nähe anfangen zu tanzen", "Noch mal Blickkontakt suchen, bevor du losgehst", "Zu ihr und der Gruppe hingehen"]'::jsonb, 'Abends ändert sich die Situation schnell. Wer zögert, macht aus Signalen verpasste Chancen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b5ec6ba9-5bbb-4681-a239-50a711d681dd', 'de', 'Warum funktionieren Opener mit einer Streitfrage so gut?', '["Sie schaffen einen verspielten Konflikt, der sexuelle Spannung aufbaut", "Ihre Meinung entscheidet die Frage, und dadurch fühlt sie sich wichtig", "Sie zeigen sozialen Beweis (du hast mit einem Kumpel geredet)"]'::jsonb, 'Eine kleine Streitfrage lädt sie ein, ihre Meinung zu sagen. So fühlt sie sich geschätzt und einbezogen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b723c51c-c180-4bd0-900c-be66fdc3c190', 'de', 'Was ist der größte Unterschied zwischen Höflichkeit und Offenheit?', '["Der Tonfall", "Wie oft sie lächelt", "Wie sehr ihr euch beide einbringt", "Die körperliche Nähe"]'::jsonb, 'Offenheit heißt mitmachen und neugierig sein. Höflichkeit heißt, die Situation angenehm zu halten.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b765cb2c-14d9-49bf-b793-eeb611ababea', 'de', 'Was passiert, wenn du nur unter perfekten Bedingungen ansprichst?', '["Jedes Ansprechen fühlt sich wichtiger an, weil es so selten ist", "Du sprichst viel seltener an, als wenn du ständig auf Leute zugehst", "Deine Ansprachen werden besser, weil du wählerisch bist"]'::jsonb, 'Wer auf perfekte Bedingungen wartet, spricht seltener an, und jedes Mal steht mehr unter Druck.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b76c6af0-9df1-46cb-92cc-9c07b2d1404f', 'de', 'Warum nimmt ein Zeitlimit so wirksam Druck raus?', '["Sie weiß, dass sie nicht in einem endlosen Gespräch mit einem Fremden feststeckt", "Es zeigt, dass du ihre Zeit respektierst und nicht verschwendest", "Bei wenig Zeit ist das Risiko einer peinlichen Abfuhr geringer"]'::jsonb, 'Wenn du sagst, dass du nicht lange bleibst, nimmt das Druck raus. Setz es gleich am Anfang ein.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b86940dc-da66-4fd6-a19f-bbbca988a036', 'de', 'Welche körperlichen Anpassungen sorgen dafür, dass du weniger Nervosität ausstrahlst?', '["Gleichmäßig gehen, weder hastig noch zögerlich", "Die Schultern locker nach hinten und unten, nicht hochgezogen oder gekrümmt", "Die Frau fixieren, um Fokus und Absicht zu zeigen"]'::jsonb, 'Ein gleichmäßiges Tempo und lockere Schultern verringern sichtbare Anspannung, bevor du etwas sagst.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ba3e426f-7282-4d49-a10f-46c3512816fc', 'de', 'Sie reagiert neutral, du machst einen klaren Schritt, und sie sagt Nein. Was solltest du tun?', '["Dich bedanken und ruhig gehen", "Es anders formulieren und noch mal versuchen", "Dein Interesse rechtfertigen", "Das Thema wechseln"]'::jsonb, 'Ein Nein ist eine klare Grenze. Nimm es ruhig an und geh gelassen.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('bb7584e8-d1df-4dc9-a2bf-59a289ba6852', 'de', 'Was passiert, wenn du nur reagierst, statt die Richtung vorzugeben?', '["Das Gespräch brauchte einfach mehr Zeit, um voranzukommen", "Du gibst den Rahmen ab, und sie wird den nächsten Schritt nicht für dich machen", "Das Timing verbessert sich, bevor du weitergehst"]'::jsonb, 'Wenn du nicht mehr führst, verliert das Gespräch an Schwung. Ergreif die Initiative und bring es voran.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('bc490fe2-1fae-42f6-b95e-718da8dccc05', 'de', 'Warum ist es für ein respektvolles Gespräch so wichtig, früh Signale zu lesen?', '["Ihr erstes Verhalten zeigt, wie viel Spielraum du zum Weitermachen hast", "Frauen müssen sich sicher fühlen, bevor sie Interesse zeigen können", "Frühe Signale verhindern, dass du Grenzen überschreitest, die sie nicht geöffnet hat", "Alle oben genannten"]'::jsonb, 'Ihr Wohlgefühl kommt zuerst. Nutz die Signale, um zu entscheiden, ob du weitermachst oder dich zurücknimmst.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('bc5cb121-8a63-45f6-8e11-7d46e1ff9ec2', 'de', 'Welche Eigenschaften stärken den Rahmen eines Mannes?', '["Klarer Glaube an sich selbst", "Gelassenheit gegenüber Abfuhren", "Die Richtung vorgeben", "Nach Bestätigung suchen"]'::jsonb, 'Klarer Glaube an dich selbst und Führung stärken deinen Rahmen. Vermeide alles, was nach Zustimmung heischt.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c1dd9ccd-317b-4320-a1f4-5bbb6553f846', 'de', 'Du sprichst sie an. Sie lächelt, dreht sich zu dir und fragt freundlich: „Was gibt’s?“', '["Offen: Sie ist offen. Bau das Gespräch weiter auf", "Höflich: Sie ist nur freundlich. Teste erst mit einem weiteren Satz", "Unklar: Du brauchst mehr Infos, um ihr Interesse einzuschätzen"]'::jsonb, 'Wenn sie sich mit Fragen und offener Haltung einbringt, ist Interesse da. Halt den Schwung.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c229e235-368e-47aa-9571-c1345d6402cf', 'de', 'Du sprichst eine Frau im Café an. Mit welchem Opener fühlt sie sich geschätzt?', '["„Hi, bist du öfter hier?“", "„Ich brauch mal die Meinung einer Frau.“", "„Was trinkst du da?“", "„Du siehst heute gut aus.“"]'::jsonb, 'Wenn du ausdrücklich nach ihrem Urteil fragst, wird sie wichtig, und das weckt ihr Interesse.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c321230f-a277-4593-bdeb-01167899a30c', 'de', 'Supermarkt. Du sagst: „Du wirkst wie ein totaler Gesundheitsfreak. Stimmt’s?“ Sie lacht. Was funktioniert hier?', '["Die verspielte Vermutung hat sie einbezogen und sofort Geplänkel erzeugt", "Du hast mit einer mutigen Aussage Selbstbewusstsein gezeigt", "Du hast sie neugierig gemacht, warum du sie für gesundheitsbewusst hältst"]'::jsonb, 'Lachen plus Korrektur heißt, sie ist dabei. Bleib in diesem verspielten Rahmen und bau ihn aus.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c36a094c-8b8b-4c97-b801-f551071a78ed', 'de', 'Sie trägt künstlerische Vintage-Kleidung. Welcher Opener nutzt eine Vermutung wirksam?', '["„Ich liebe deinen Stil. Wo kaufst du normalerweise ein?“", "„Du siehst aus, als würdest du was Kreatives machen. Stimmt’s?“", "„Du gehst bestimmt oft in Secondhandläden, oder?“", "B oder C"]'::jsonb, 'Bei beiden muss sie sich einbringen, um zu bestätigen, zu widersprechen oder zu erklären.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c387493a-0ebd-41c3-b083-1a639c5a593d', 'de', 'Warum schwächt eine frühe Entschuldigung deinen Opener?', '["Sie senkt deinen Status", "Sie zeigt, dass du störst", "Sie gibt ihr die Kontrolle", "Alle oben genannten"]'::jsonb, 'Wer sich entschuldigt, stellt sich als Störung dar. Steig lieber so ein, als gehörtest du dazu.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
commit;
